function initialToolValues(type,context){
 const category=context.formulation_type||context.product_category||"";
 const labels={classical_medicine:"Classical Ayurveda",proprietary_medicine:"Proprietary formulation",new_non_classical_drug:"New / non-classical medicine",phytopharmaceutical:"Phytopharmaceutical",ayurveda_aahar_nutraceutical:"Ayurveda-Aahara / nutraceutical",cosmetic:"Cosmetic"};
 const categoryLabel=labels[category]||category;
 const values={};
 if(type==="formulation"){
  if(categoryLabel){values.classical_source=category==="classical_medicine"?"Yes":context.classical_source||"";values.developed_by_org=context.developed_by_org||"";values.product_category=category==="cosmetic"?"Cosmetic":category==="ayurveda_aahar_nutraceutical"?"Ayurveda-Aahara / Food":"Medicine"}if(context.formulation_description||context.source_text)values.description=context.formulation_description||context.source_text;if(context.guidance_areas)values.guidance_areas=Array.isArray(context.guidance_areas)?context.guidance_areas:[context.guidance_areas]
 } else if(type==="patent"){
  if(context.ip_type){const ips=Array.isArray(context.ip_type)?context.ip_type:[context.ip_type];values.ip_type=ips.map(ip=>display(ip).replace(/^./,c=>c.toUpperCase()))}
  if(categoryLabel)values.formulation_type=categoryLabel;
  if(context.jurisdiction)values.jurisdiction=context.jurisdiction==="international"?"International":"India";
  if(context.protection_subject)values.protection_subject=context.protection_subject;
  if(context.invention_feature)values.invention_feature=context.invention_feature;
 } else if(type==="abs"){
  for(const key of ["biological_resource","origin_country","intended_activity","associated_traditional_knowledge","ipr_planned"])if(context[key])values[key]=context[key];
 } else if(type==="tkdl"){
  if(context.formulation_name)values.formulation_name=context.formulation_name;
  if(context.ingredients)values.ingredients=context.ingredients;
  if(context.classical_source)values.classical_source=context.classical_source;
  if(context.traditional_use){const uses=Array.isArray(context.traditional_use)?context.traditional_use:[context.traditional_use];const options=TOOL_FLOWS.tkdl.fields.find(field=>field.key==="traditional_use").options;values.traditional_use=uses.filter(use=>options.includes(use));if(uses.some(use=>!options.includes(use)))values.traditional_use_details=uses.filter(use=>!options.includes(use)).join(", ")}
  if(context.patent_context)values.patent_context=context.patent_context;
 } else if(type==="export"){
  for(const key of ["destination_country","intended_activity","india_manufacturing_status"])if(context[key])values[key]=context[key];
  if(context.guidance_areas){const areas=Array.isArray(context.guidance_areas)?context.guidance_areas:[context.guidance_areas];const options=TOOL_FLOWS.export.fields.find(field=>field.key==="guidance_areas").options;values.guidance_areas=areas.filter(area=>options.includes(area))}
  if(context.product_type){const options=TOOL_FLOWS.export.fields.find(field=>field.key==="product_type").options;if(options.includes(context.product_type))values.product_type=context.product_type}
  else if(categoryLabel)values.product_type=categoryLabel;
 }
 return values;
}
