function readSharedContext(){try{return JSON.parse(sessionStorage.getItem(SHARED_CONTEXT_KEY)||"{}")||{}}catch{return {}}}
function contextText(context){return Object.entries(context||{}).filter(([,value])=>value!==null&&value!==undefined&&value!==false&&value!=="unknown"&&value!=="not_applicable"&&value!=="").map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(", "):typeof value==="object"?JSON.stringify(value):String(value).replaceAll("_"," ")}`).join("\n")}
function mergeKnownContext(previous,known){const next={...previous};for(const [key,value] of Object.entries(known||{})){if(value!==null&&value!==undefined&&value!==false&&value!=="unknown"&&value!=="not_applicable"&&value!=="")next[key]=value}return next}

