function makeChatTitle(question){let text=question.replace(/\s+/g," ").trim().replace(/[?!.]+$/,""),lower=text.toLowerCase();if(/classical ayurveda formulation/.test(lower)&&/patent/.test(lower))return "Classical Ayurveda patentability";if(/role of tkdl/.test(lower))return "Role of TKDL in Ayurveda patents";if(/section\s*3\s*\(?p\)?/.test(lower))return "Section 3(p) of Patents Act";text=text.replace(/^(what is|what are|can|could|does|do|is|are|how does|how do|tell me about)\s+/i,"").replace(/\bof the Patents Act,?\s*1970\b/i,"of Patents Act").replace(/\s+/g," ").trim();let words=text.split(" "),title=words.slice(0,7).join(" ");return (words.length>7?title+"…":title)||"New conversation"}
