function Brand({compact=false,locale="en"}){return <div className="brand"><span className="brand-mark">IP</span><span><strong>IP-SAKTI Sahayak</strong>{!compact&&<small>{tr(locale,"Ayurveda IPR, Regulatory & ABS Guidance")}</small>}</span></div>}
