 const submit=e=>{e.preventDefault();if(Array.isArray(value)?!value.length:!String(value).trim())return;const answer=Array.isArray(value)&&otherDetail.trim()? [...value,`Other detail: ${otherDetail.trim()}`]:value;onContinue(item,answer)};
