  <div className={"result-status compact "+(r.safe_abstention?"abstained":"")}><b>{tr(locale,clarify?(isAnswered?"Thanks, I’ve saved that detail":"A little more information will help") :r.prior_art?.record_level_search_abstained?"TKDL record search unavailable":r.safe_abstention?"Authoritative evidence unavailable":r.status==="needs_review"?"Citation review required":"Grounded response")}</b><span className={"confidence "+r.confidence}>{tr(locale,display(r.confidence))}</span></div>
