 async function submit(event){event.preventDefault();if(!reason.trim())return;setBusy(true);setError("");try{const response=await fetch(API_ROOT+"/v1/escalations",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({question:context.question,assistant_response:context.assistantResponse,reason:reason.trim(),contact_email:email.trim(),user_id:actorId(),jurisdiction:context.jurisdiction,sources_cited:context.sources})});const data=await response.json();if(!response.ok)throw new Error(data.detail||"The request could not be prepared.");setResult(data)}catch(e){setError(e.message||"The request could not be prepared.")}finally{setBusy(false)}}
