 const language=locale,[chats,setChats]=useState(readChats),[activeChatId,setActiveChatId]=useState(null),[error,setError]=useState(""),[loading,setLoading]=useState(false),[listening,setListening]=useState(false),[note,setNote]=useState(""),[menu,setMenu]=useState(false),[escalation,setEscalation]=useState(null);
 const file=useRef(null),rec=useRef(null),end=useRef(null),activeChat=chats.find(chat=>chat.id===activeChatId),messages=activeChat?.messages||[],has=messages.length>0;
