 const suggestions=jurisdiction==="international"?INTERNATIONAL_SUGGESTIONS:SUGGESTIONS;
 useEffect(()=>{localStorage.setItem(CHAT_STORAGE_KEY,JSON.stringify(chats))},[chats]);
