 function continueQuery(question,answer){const previous=[...messages].reverse().find(m=>m.type==="assistant"),original=previous?.original||"",context=previous?.context?"\n\nGuidance tool context (user-supplied details only):\n"+previous.context:"",value=Array.isArray(answer)?answer.join("; "):answer;send(original+context+`\n\nClarification answer field: ${question.field} = ${String(value).trim()}`)}
 function voice(){if(listening)return rec.current?.stop();const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return setNote("Voice input is not supported by this browser. Please type your question.");const recognition=new Recognition();recognition.lang=({hi:"hi-IN",ta:"ta-IN",te:"te-IN",ml:"ml-IN"})[language]||"en-IN";recognition.onresult=e=>setQ(v=>v?v+" "+e.results[0][0].transcript:e.results[0][0].transcript);recognition.onerror=()=>setNote("Voice input could not be captured. Please try again or type your question.");recognition.onend=()=>setListening(false);rec.current=recognition;setListening(true);recognition.start()}
 function fileChange(e){const selected=e.target.files?.[0];if(!selected)return;if(selected.type!=="application/pdf")return setError("Please select a PDF document.");setNote("PDF selected: "+selected.name+". It will not be sent as evidence because document processing is not currently available.")}
  return <main className="app-shell"><aside className={"sidebar "+(menu?"open":"")}><div className="sidebar-brand"><Brand compact locale={locale}/><button className="mobile-close" onClick={()=>setMenu(false)} aria-label={tr(locale,"Close")}>×</button></div><button className="new-query" onClick={startNewChat}>＋ {tr(locale,"New Chat")}</button><div className="sidebar-section"><p>{tr(locale,"RECENT CHATS")}</p>{chats.length?<div className="recent-chats">{chats.map(chat=><div className={"recent-chat "+(chat.id===activeChatId?"active":"")} key={chat.id} onClick={()=>openChat(chat.id)} onKeyDown={e=>{if(e.key==="Enter"||e.key===" ")openChat(chat.id)}} role="button" tabIndex="0" title={chat.title}><span>{chat.title}</span><button className="delete-chat" aria-label={`${tr(locale,"Delete")} ${chat.title}`} title={tr(locale,"Delete chat")} onClick={e=>deleteChat(e,chat.id)}>×</button></div>)}</div>:<div className="empty-recent">{tr(locale,"No conversations yet.")}<br/>{tr(locale,"Start a new conversation with Sahayak.")}</div>}</div><nav className="sidebar-nav"><button onClick={()=>navigate("/sources")}>▤ {tr(locale,"Sources")}</button><button onClick={()=>navigate("/tools")}>⌘ {tr(locale,"Guidance Tools")}</button><button onClick={()=>navigate("/my-requests")}>▧ {tr(locale,"My Requests")}</button>{["facilitator","admin"].includes(user?.role)&&<button onClick={()=>navigate("/facilitator")}>◎ {tr(locale,"Facilitator queue")}</button>}<button onClick={()=>navigate("/settings")}>⚙ {tr(locale,"Settings")}</button></nav><button className="logout" onClick={onLogout}>↪ {tr(locale,"Logout")}</button></aside><div className="app-content"><header className="app-header"><button className="menu-button" onClick={()=>setMenu(true)} aria-label={tr(locale,"Open menu")}>☰</button><Brand compact locale={locale}/><div className="header-controls"><LanguageSelect locale={locale} onLocaleChange={onLocaleChange}/><span className="header-jurisdiction">{tr(locale,jurisdiction==="india"?"India":"International")}</span></div></header><section className={"workspace chat-workspace "+(has?"has-conversation":"")}>{!has&&<div className="workspace-intro chat-welcome"><p>{tr(locale,greeting)}</p><h1>{tr(locale,"How can Sahayak help?")}</h1><span>{tr(locale,"Ask an Ayurveda IPR, regulatory or ABS question.")}</span></div>}<div className="chat-jurisdiction"><span>{tr(locale,"JURISDICTION")}</span><div className="jurisdiction-switch">{[["india","India"],["international","International"]].map(([value,label])=><button type="button" key={value} className={jurisdiction===value?"active":""} onClick={()=>setActiveJurisdiction(value)}>{tr(locale,label)}</button>)}</div></div>{!has&&<section className="suggested"><p className="eyebrow">{tr(locale,"SUGGESTED QUESTIONS")}</p><div>{suggestions.map(s=><button key={s} onClick={()=>setQ(s)}>{tr(locale,s)}<span>→</span></button>)}</div></section>}<section className="conversation">{messages.map((m,i)=>m.type==="user"?<article className="chat-message user-message" key={i}><div className="message-label">{tr(locale,"YOU")}</div><div className="user-bubble">{m.text}</div></article>:<Assistant message={m} key={i} isAnswered={messages.slice(i+1).some(next=>next.type==="user")} onContinue={continueQuery} onEscalate={requestEscalation} locale={locale}/>)}{loading&&<article className="chat-message assistant-message"><div className="message-label">SAHAYAK</div><div className="thinking-bubble"><i/> <i/> <i/> {tr(locale,"Thinking...")}</div></article>}{error&&<p className="error" role="alert">{tr(locale,error)}</p>}<div ref={end}/></section>{note&&<p className="inline-note">{tr(locale,note)}</p>}<Composer value={q} setValue={setQ} onSend={ask} loading={loading} onVoice={voice} listening={listening} fileRef={file} onFile={fileChange} locale={locale}/></section></div>{escalation&&<EscalationForm context={escalation} token={token} onClose={()=>setEscalation(null)} locale={locale}/>}</main>
