function Tools({navigate,locale,onLocaleChange}){return <Simple title="Choose a guided starting point" navigate={navigate} locale={locale} onLocaleChange={onLocaleChange}><p className="page-lead">{tr(locale,"Answer a few focused questions, review the details, then continue in the same Sahayak conversation.")}</p><div className="tool-grid">{[["Formulation Classification","/formulation"],["Patent & IP Guidance","/patent"],["ABS Compliance","/abs-check"],["TKDL / Prior-Art","/tkdl"],["International Export & Market Entry","/export"]].map(([title,path])=><article key={path}><h2>{tr(locale,title)}</h2><button className="secondary" onClick={()=>navigate(path)}>{tr(locale,"Start guided questions →")}</button></article>)}</div></Simple>}
function Tool({type,navigate,token,locale,onLocaleChange}){
 const flow=TOOL_FLOWS[type],shared=readSharedContext();
 const [initialValues]=useState(()=>initialToolValues(type,shared));
 const [values,setValues]=useState(initialValues),[step,setStep]=useState(0),[loading,setLoading]=useState(false),[error,setError]=useState(""),[result,setResult]=useState(null);
 const steps=flow.fields.map(field=>({...field,field:field.key,question:field.label,input_type:field.type==="free_text"?"textarea":field.type==="single_select"&&field.options.join("|")==="Yes|No|Not sure"?"yes_no_not_sure":field.type,allow_multiple:field.type==="multi_select",required:true})).filter(field=>{const value=initialValues[field.key];if(field.input_type==="multi_select")return !Array.isArray(value)||!value.length;if(field.input_type==="single_select"||field.input_type==="yes_no_not_sure")return !field.options.includes(value);return !String(value||"").trim()});
 const current=steps[step],review=step>=steps.length;
 function update(key,value){setValues(old=>({...old,[key]:value}))}
 function back(){setError("");setStep(index=>Math.max(0,Math.min(index,steps.length-1)))}
 async function prepare(){
  setLoading(true);setError("");let workflowResult=null;
  try{
   if(type==="formulation"){
    const source=[values.classical_source==="Yes"?"Based on a classical Ayurvedic text.":values.classical_source==="No"?"Not based on a classical Ayurvedic text.":"",values.developed_by_org==="Yes"?"Newly developed by our organization.":values.developed_by_org==="No"?"Not newly developed by our organization.":"",values.description||""].filter(Boolean).join(" ");
    const response=await fetch(FORMULATION_API,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({product_type:values.product_category||"",source_text:source,intended_question:(values.guidance_areas||[]).join(", ")||"Classify the formulation",classical_source:values.classical_source||"",newly_developed:values.developed_by_org||""})});workflowResult=await response.json();if(!response.ok)throw new Error(workflowResult.detail||"Classification could not be completed.");
   }else if(type==="abs"){
    const response=await fetch(ABS_API,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({biological_resource:values.biological_resource||"",access_origin:values.origin_country||"",commercial_activity:values.intended_activity||""})});workflowResult=await response.json();if(!response.ok)throw new Error(workflowResult.detail||"The ABS readiness check could not be prepared.");
   }else if(type==="tkdl"){
    const claim=[values.formulation_name&&`Formulation: ${values.formulation_name}`,values.ingredients&&`Main ingredients: ${values.ingredients}`,values.classical_source&&`Classical source: ${values.classical_source}`,values.traditional_use&&`Traditional use: ${values.traditional_use.join(", ")}`,values.traditional_use_details&&`Other traditional use: ${values.traditional_use_details}`].filter(Boolean).join(". ");
    const response=await fetch(TKDL_API,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({claim,patent_context:`Specific invention or patent context: ${values.patent_context||"Not sure"}`,jurisdiction:shared.jurisdiction||"india"})});workflowResult=await response.json();if(!response.ok)throw new Error(workflowResult.detail||"The prior-art pointer could not be prepared.");
   }
   setResult(workflowResult);setStep(steps.length);
  }catch(e){setError(e.message||"This guidance tool is temporarily unavailable.")}finally{setLoading(false)}
 }
 function continueToChat(){
  const facts={...shared,...values};
  if(type==="formulation"){if(result?.category&&result.category!=="needs_clarification")facts.formulation_type=result.category;else delete facts.formulation_type}
  if(type==="patent")facts.ip_type=values.ip_type;
  if(type==="export"){facts.jurisdiction="international";facts.export=true}
  if(type==="patent"&&values.jurisdiction){facts.jurisdiction_scope=values.jurisdiction==="Both / Compare"?"both":values.jurisdiction.toLowerCase();facts.jurisdiction=values.jurisdiction==="International"?"international":values.jurisdiction==="India"?"india":shared.jurisdiction||"india"}
  if(type==="tkdl")facts.jurisdiction=shared.jurisdiction||"india";
  const summary=flow.fields.map(field=>`${field.key}: ${Array.isArray(values[field.key])?values[field.key].join(", "):values[field.key]||"Not provided"}${field.otherKey&&values[field.otherKey]?`\n${field.otherKey}: ${values[field.otherKey]}`:""}`).join("\n");
  const resultContext=result?.classification?`\nClassification: ${result.classification}\nReason: ${result.reason}\nConfidence: ${result.confidence}\nClarification needed: ${result.needs_clarification?"Yes":"No"}\n${result.clarification_question||""}`:result?.status?`\nWorkflow status: ${result.status}\n${result.next_step||result.disclaimer||""}`:"";
  const context=`${summary}${resultContext}`;sessionStorage.setItem(SHARED_CONTEXT_KEY,JSON.stringify(facts));sessionStorage.setItem("ip-sakti-tool-context",JSON.stringify({context,category:facts.formulation_type||"unknown",type,jurisdiction:facts.jurisdiction||shared.jurisdiction||"india"}));
  const prompts={formulation:`Please provide evidence-based guidance about this formulation. I want help with: ${(values.guidance_areas||[]).join(", ")||"classification"}.`,patent:`Can I protect this formulation? I am considering ${(values.ip_type||[]).join(", ")||"IP protection"}. I want to protect: ${values.protection_subject||"the product or process"}. Main feature: ${values.invention_feature||"not specified"}.`,abs:`What ABS requirements apply to this activity? Biological resource: ${values.biological_resource||"not provided"}.`,tkdl:"Is this Ayurvedic formulation already documented as traditional knowledge?",export:`How can I export my ${values.product_type||"Ayurvedic product"} from India to ${values.destination_country||"the target market"}?`};
  sessionStorage.setItem("ip-sakti-tool-question",prompts[type]);navigate("/app");
 }
 function renderQuestion(field){if(field.input_type==="country")return <><input className="guided-input" list="guided-country-list" value={values[field.key]||""} onChange={e=>update(field.key,e.target.value)} placeholder={tr(locale,"Type or choose a country")}/><datalist id="guided-country-list">{COUNTRIES.map(country=><option value={country} key={country}/>)}</datalist></>;if(field.input_type==="text")return <input className="guided-input" type="text" value={values[field.key]||""} onChange={e=>update(field.key,e.target.value)} placeholder={tr(locale,"Type a short answer")}/>;if(field.input_type==="textarea")return <textarea className="guided-textarea" value={values[field.key]||""} onChange={e=>update(field.key,e.target.value)} placeholder={tr(locale,"Type your answer")}/>;if(field.input_type==="multi_select")return <><div className="guided-options multi">{field.options.map(option=>{const selected=(values[field.key]||[]).includes(option);return <label className={selected?"selected":""} key={option}><input type="checkbox" checked={selected} onChange={()=>update(field.key,selected?values[field.key].filter(value=>value!==option):[...(values[field.key]||[]),option])}/>{tr(locale,option)}</label>})}</div>{field.otherKey&&(values[field.key]||[]).includes("Other")&&<label className="guided-other">{tr(locale,field.otherLabel)}<textarea className="guided-textarea" value={values[field.otherKey]||""} onChange={e=>update(field.otherKey,e.target.value)} placeholder={tr(locale,"Add an optional detail")}/></label>}</>;return <div className="guided-options">{field.options.map(option=><button type="button" className={values[field.key]===option?"selected":""} key={option} onClick={()=>update(field.key,option)}>{tr(locale,option)}</button>)}</div>}
 return <Simple title={flow.title} navigate={navigate} locale={locale} onLocaleChange={onLocaleChange}><section className="guided-flow" aria-live="polite">{!review?<><div className="guided-progress">{tr(locale,`Question ${step+1} of ${steps.length}`)}</div><h2>{tr(locale,current.question)}</h2>{renderQuestion(current)}{error&&<p className="error" role="alert">{tr(locale,error)}</p>}<div className="guided-actions"><button type="button" className="secondary" onClick={back} disabled={step===0}>{tr(locale,"← Back")}</button><button type="button" className="primary" onClick={()=>step===steps.length-1?prepare():setStep(index=>index+1)} disabled={loading||!current||(Array.isArray(values[current.key])?!values[current.key].length:!String(values[current.key]||"").trim())}>{tr(locale,loading?"Preparing…":step===steps.length-1?"Review details →":"Next →")}</button></div></>:<><p className="eyebrow">{tr(locale,"REVIEW YOUR DETAILS")}</p><h2>{tr(locale,"Your information")}</h2><dl className="guided-summary">{flow.fields.map(field=><div key={field.key}><dt>{tr(locale,field.label)}</dt><dd>{Array.isArray(values[field.key])?values[field.key].map(x=>tr(locale,x)).join(", "):tr(locale,values[field.key]||"Not provided")}{field.otherKey&&values[field.otherKey]?` — ${values[field.otherKey]}`:""}</dd></div>)}</dl>{result?.classification&&<section className="classification-result"><h3>{tr(locale,"Formulation classification")}</h3><strong className="classification-category">{tr(locale,result.classification)}</strong><p>{tr(locale,result.reason)}</p><p>{tr(locale,"Confidence")}: {tr(locale,display(result.confidence))}</p><p>{tr(locale,"Clarification needed")}: {tr(locale,result.needs_clarification?"Yes":"No")}</p>{result.needs_clarification&&result.clarification_question&&<p>{tr(locale,result.clarification_question)}</p>}<p>{tr(locale,result.next_step)}</p></section>}{result?.status&&<p className="inline-note">{tr(locale,result.status.replaceAll("_"," "))}. {tr(locale,result.next_step||result.disclaimer)}</p>}{error&&<p className="error" role="alert">{tr(locale,error)}</p>}<div className="guided-actions"><button type="button" className="secondary" onClick={back}>{tr(locale,"← Back to questions")}</button><button type="button" className="primary" onClick={continueToChat}>{tr(locale,"Continue with Sahayak →")}</button></div></>}</section></Simple>
}
function Settings({navigate,onLogout,locale,onLocaleChange}){return <Simple title="Workspace preferences" navigate={navigate} locale={locale} onLocaleChange={onLocaleChange}><div className="settings-grid"><section><h2>{tr(locale,"Profile")}</h2><label>{tr(locale,"Name")}<input disabled placeholder={tr(locale,"Available with account profiles")}/></label></section><section><h2>{tr(locale,"Account")}</h2><button className="secondary" onClick={onLogout}>{tr(locale,"Logout")}</button></section></div></Simple>}
export default function App(){
 let[path,setPath]=useState(window.location.pathname),[auth,setAuth]=useState(()=>{try{return JSON.parse(sessionStorage.getItem("ip-sakti-auth-session")||"null")}catch{return null}}),[checked,setChecked]=useState(false),[locale,setLocale]=useState(()=>{const saved=localStorage.getItem("ipSaktiLocale");return LANGUAGES.some(([code])=>code===saved)?saved:"en"});
 const changeLocale=value=>{if(LANGUAGES.some(([code])=>code===value))setLocale(value)};
 useEffect(()=>{localStorage.setItem("ipSaktiLocale",locale)},[locale]);
 useEffect(()=>{let x=()=>setPath(window.location.pathname);window.addEventListener("popstate",x);return()=>window.removeEventListener("popstate",x)},[]);
 useEffect(()=>{if(!auth?.access_token){setChecked(true);return}fetch(API_ROOT+"/v1/auth/me",{headers:{Authorization:`Bearer ${auth.access_token}`}}).then(response=>{if(!response.ok)throw new Error("Session expired");return response.json()}).then(data=>setAuth(old=>({...old,user:data.user}))).catch(()=>{sessionStorage.removeItem("ip-sakti-auth-session");setAuth(null)}).finally(()=>setChecked(true))},[]);
 let navigate=to=>{window.history.pushState({},"",to);setPath(to);window.scrollTo(0,0)},complete=session=>{sessionStorage.setItem("ip-sakti-auth-session",JSON.stringify(session));setAuth(session);setChecked(true);navigate("/app")},logout=()=>{sessionStorage.removeItem("ip-sakti-auth-session");setAuth(null);navigate("/login")},protectedRoutes=["/app","/settings","/tools","/formulation","/patent","/abs-check","/tkdl","/export","/facilitator","/my-requests"];
 if(protectedRoutes.includes(path)&&!checked)return <main className="auth-page"><div className="auth-language"><LanguageSelect locale={locale} onLocaleChange={changeLocale}/></div><p>{tr(locale,"Checking sign-in…")}</p></main>;
 if(protectedRoutes.includes(path)&&!auth)return <Auth mode="login" navigate={navigate} onComplete={complete} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/login")return <Auth mode="login" navigate={navigate} onComplete={complete} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/signup")return <Auth mode="signup" navigate={navigate} onComplete={complete} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/app")return <Dashboard navigate={navigate} onLogout={logout} token={auth?.access_token} user={auth?.user} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/settings")return <Settings navigate={navigate} onLogout={logout} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/tools")return <Tools navigate={navigate} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/formulation")return <Tool type="formulation" navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/patent")return <Tool type="patent" navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/export")return <Tool type="export" navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/abs-check")return <Tool type="abs" navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/tkdl")return <Tool type="tkdl" navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/my-requests")return <MyRequests navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>;
 if(path==="/facilitator")return ["facilitator","admin"].includes(auth?.user?.role)?<Facilitator navigate={navigate} token={auth.access_token} locale={locale} onLocaleChange={changeLocale}/>:<Simple title="Facilitator access required" navigate={navigate} locale={locale} onLocaleChange={changeLocale}><p>{tr(locale,"This queue is available to facilitator and admin accounts.")}</p></Simple>;
 if(path==="/sources")return <SourcesPage navigate={navigate} locale={locale} onLocaleChange={changeLocale}/>;
 return <Landing navigate={navigate} locale={locale} onLocaleChange={changeLocale}/>;
}
